<script setup lang="ts">
/**
 * Blue Seal circular brand mark (the official engraved seal), inline so its
 * colour is driven by CSS `currentColor`.
 *
 * Two distinct artworks (not just two colours):
 *   - tone="on-light" → DARK mark (solid badge, emblem knocked out). Sits on a
 *                       LIGHT surface; give it an INK colour, e.g.
 *                       style="color: var(--bs-blue)".
 *   - tone="on-dark"  → LIGHT mark (positive line emblem + ring). Sits on a
 *                       DARK surface; give it a LIGHT colour, e.g.
 *                       style="color: var(--bs-beige)" or text-white.
 *
 * Size by setting a height — width tracks the 1:1 viewBox.
 *
 *   <BlueSealSeal tone="on-light" class="h-10" style="color: var(--bs-blue)" />
 *   <BlueSealSeal tone="on-dark"  class="h-10" style="color: var(--bs-beige)" />
 */
withDefaults(
  defineProps<{
    /** Which treatment to render. Defaults to the light-surface (knockout) badge. */
    tone?: "on-light" | "on-dark";
    /** Accessible name. Ignored when `decorative`. */
    title?: string;
    /** Hide from assistive tech — use when the mark sits beside a visible text label. */
    decorative?: boolean;
  }>(),
  { tone: "on-light", title: "Blue Seal", decorative: false },
);
</script>

